<script setup lang="ts">
import {onScopeDispose,shallowRef} from 'vue'
import {Descriptions as ADescriptions,DescriptionsItem as ADescriptionsItem} from 'ant-design-vue'
import {deviceState,usableDevice,type ResponseDevice} from '../responseDevices'
import {formatTime} from '../types'
defineProps<{device:ResponseDevice|null;observedAt?:string}>()
const emit=defineEmits<{close:[];actions:[device:ResponseDevice];respond:[device:ResponseDevice]}>()
const now=shallowRef(Date.now()),timer=setInterval(()=>{now.value=Date.now()},5000);onScopeDispose(()=>clearInterval(timer))
</script>
<template><a-drawer title="联动设备详情" :open="device!==null" width="min(720px, 100vw)" @close="emit('close')"><template v-if="device"><a-alert type="info" show-icon message="目录来自探针心跳。具备提交条件仅表示预检通过，提交时平台与采集器仍会核对权限、身份、配置和目标范围。" class="section-gap"/><a-descriptions bordered :column="1" size="small"><a-descriptions-item label="设备标识">{{device.device_id}}</a-descriptions-item><a-descriptions-item label="连接器标识">{{device.connector_id}}</a-descriptions-item><a-descriptions-item label="执行探针">{{device.sensor_name}} · {{device.sensor_id}}</a-descriptions-item><a-descriptions-item label="探针注册身份"><span class="technical">{{device.registration_id}}</span></a-descriptions-item><a-descriptions-item label="当前条件">{{deviceState(device,now)}}</a-descriptions-item><a-descriptions-item label="设备核验状态">{{device.status==='ready'?'身份已核验':device.status==='unverified'?'身份待核验':'设备不可用'}}</a-descriptions-item><a-descriptions-item label="接口版本">{{device.version}}</a-descriptions-item><a-descriptions-item label="配置 SHA-256"><span class="technical device-hash">{{device.config_sha256}}</span></a-descriptions-item><a-descriptions-item label="最长封禁">{{device.max_ttl_seconds.toLocaleString()}} 秒</a-descriptions-item><a-descriptions-item label="设备核验时间">{{device.observation==='pending'?'尚未核验':formatTime(device.observed_at)}}</a-descriptions-item><a-descriptions-item label="平台接收心跳">{{formatTime(device.last_seen??'')}}</a-descriptions-item><a-descriptions-item label="目录读取时间">{{formatTime(observedAt??'')}}</a-descriptions-item></a-descriptions><p class="page-description section-gap">设备管理地址和凭据保留在执行采集器。本地配置文件调整后需重启采集器；设备配置回读与实际流量阻断效果分别核验。</p><div class="filter-actions"><a-button type="primary" :disabled="!usableDevice(device,now)" @click="emit('respond',device)">限时封禁</a-button><a-button @click="emit('actions',device)">相关动作</a-button><a-button @click="emit('close')">关闭</a-button></div></template></a-drawer></template>
<style scoped>.device-hash{overflow-wrap:anywhere;word-break:break-all}</style>
